import{_ as o,C as i,o as a,c as r,a2 as s,b as c,w as t,a as d,E as n,a3 as p}from"./chunks/framework.DBSoX6Zw.js";const v=JSON.parse('{"title":"Architecture — GitHub Actions (.github/)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/github.md","filePath":"architecture/github.md"}'),h={name:"architecture/github.md"};function u(m,e,g,k,b,y){const l=i("Mermaid");return a(),r("div",null,[e[1]||(e[1]=s('<h1 id="architecture-—-github-actions-github" tabindex="-1">Architecture — GitHub Actions (<code>.github/</code>) <a class="header-anchor" href="#architecture-—-github-actions-github" aria-label="Permalink to &quot;Architecture — GitHub Actions (`.github/`)&quot;">​</a></h1><blockquote><p>CI/CD workflows and automation for Plik. For system-wide overview, see the root <a href="./system.html">ARCHITECTURE.md</a>.</p></blockquote><hr><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.github/</span></span>\n<span class="line"><span>├── workflows/</span></span>\n<span class="line"><span>│   ├── tests.yaml              ← CI: lint, test, docs build on push/PR</span></span>\n<span class="line"><span>│   ├── pages.yml               ← Deploy docs to gh-pages</span></span>\n<span class="line"><span>│   ├── release.yaml            ← Build release archives, Docker images, Helm chart on release</span></span>\n<span class="line"><span>│   ├── master.yaml             ← Post-merge actions on master</span></span>\n<span class="line"><span>│   ├── docker-build-pr.yaml    ← Build Docker image on PR (triggered by comment)</span></span>\n<span class="line"><span>│   └── docker-deploy-pr.yaml   ← Deploy PR image to staging (triggered by comment)</span></span>\n<span class="line"><span>└── ARCHITECTURE.md             ← this file</span></span></code></pre></div><hr><h2 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;Workflows&quot;">​</a></h2><h3 id="tests-yaml-—-ci-tests" tabindex="-1"><code>tests.yaml</code> — CI Tests <a class="header-anchor" href="#tests-yaml-—-ci-tests" aria-label="Permalink to &quot;`tests.yaml` — CI Tests&quot;">​</a></h3><p>Runs on every push and pull request. Steps:</p><ol><li>Go lint (<code>make lint</code>)</li><li>Go tests (<code>make test</code>)</li><li>Frontend tests (<code>make test-frontend</code>) — vitest unit tests for the Vue webapp</li><li>Docs build (<code>make docs</code>) — verifies VitePress builds without errors</li></ol><h3 id="pages-yml-—-github-pages-docs" tabindex="-1"><code>pages.yml</code> — GitHub Pages (Docs) <a class="header-anchor" href="#pages-yml-—-github-pages-docs" aria-label="Permalink to &quot;`pages.yml` — GitHub Pages (Docs)&quot;">​</a></h3><p>Runs on push to <code>master</code> when <code>docs/**</code> or the workflow itself changes. Deploys VitePress documentation to the <code>gh-pages</code> branch via <code>peaceiris/actions-gh-pages</code>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The <code>keep_files: true</code> flag preserves the Helm <code>index.yaml</code> on <code>gh-pages</code> (updated by the release workflow).</p></div><h3 id="release-yaml-—-tagged-release-pipeline" tabindex="-1"><code>release.yaml</code> — Tagged Release Pipeline <a class="header-anchor" href="#release-yaml-—-tagged-release-pipeline" aria-label="Permalink to &quot;`release.yaml` — Tagged Release Pipeline&quot;">​</a></h3><p>Triggered when a GitHub release is created (tag push). Runs the full release pipeline:</p><ol><li>Builds multi-arch Docker images</li><li>Builds release archives and client binaries</li><li>Packages the Helm chart and updates <code>index.yaml</code> on <code>gh-pages</code> (via <code>releaser/helm_release.sh</code>)</li><li>Uploads all artifacts (including <code>plik-helm-{version}.tgz</code>) to the GitHub release</li></ol><p>See <a href="./releaser.html">releaser/ARCHITECTURE.md</a> for the build details.</p><h3 id="master-yaml-—-docker-dev-build" tabindex="-1"><code>master.yaml</code> — Docker Dev Build <a class="header-anchor" href="#master-yaml-—-docker-dev-build" aria-label="Permalink to &quot;`master.yaml` — Docker Dev Build&quot;">​</a></h3><p>Runs on every push to <code>master</code> (only in the <code>root-gg</code> org). Builds multi-arch Docker images and pushes <code>rootgg/plik:dev</code> to Docker Hub via <code>make release-and-push-to-docker-hub</code>. This ensures the <code>dev</code> tag always reflects the latest <code>master</code> state.</p><h3 id="docker-build-pr-yaml-—-pr-docker-build" tabindex="-1"><code>docker-build-pr.yaml</code> — PR Docker Build <a class="header-anchor" href="#docker-build-pr-yaml-—-pr-docker-build" aria-label="Permalink to &quot;`docker-build-pr.yaml` — PR Docker Build&quot;">​</a></h3><p>Triggered by a <code>docker build</code> comment on a PR. Builds a Docker image tagged <code>rootgg/plik:pr-{number}</code> and pushes it to Docker Hub. Reports back with a comment.</p><h3 id="docker-deploy-pr-yaml-—-pr-docker-deploy" tabindex="-1"><code>docker-deploy-pr.yaml</code> — PR Docker Deploy <a class="header-anchor" href="#docker-deploy-pr-yaml-—-pr-docker-deploy" aria-label="Permalink to &quot;`docker-deploy-pr.yaml` — PR Docker Deploy&quot;">​</a></h3><p>Triggered by a <code>docker deploy</code> comment on a PR. Deploys the PR-specific Docker image to the staging instance at <code>plik.root.gg</code>. Reports back with a deployment confirmation comment.</p><hr><h2 id="helm-chart-release-flow" tabindex="-1">Helm Chart Release Flow <a class="header-anchor" href="#helm-chart-release-flow" aria-label="Permalink to &quot;Helm Chart Release Flow&quot;">​</a></h2>',25)),(a(),c(p,null,{default:t(()=>[n(l,{id:"mermaid-109",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20Release%5B%22GitHub%20Release%20created%22%5D%20--%3E%20ReleaseWF%5B%22release.yaml%20workflow%22%5D%0A%20%20%20%20ReleaseWF%20--%3E%20Build%5B%22Build%20archives%20%2B%20Docker%22%5D%0A%20%20%20%20ReleaseWF%20--%3E%20HelmScript%5B%22releaser%2Fhelm_release.sh%22%5D%0A%20%20%20%20HelmScript%20--%3E%20Package%5B%22Package%20plik-helm-VERSION.tgz%22%5D%0A%20%20%20%20Package%20--%3E%20Assets%5B%22GitHub%20Release%20assets%22%5D%0A%20%20%20%20HelmScript%20--%3E%20UpdateIndex%5B%22Update%20index.yaml%22%5D%0A%20%20%20%20UpdateIndex%20--%3E%20GHPages%5B%22gh-pages%20branch%22%5D%0A%20%20%20%20GHPages%20--%3E%20HelmRepo%5B%22helm%20repo%20add%20plik%3Cbr%2F%3Ehttps%3A%2F%2Froot-gg.github.io%2Fplik%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s(`<p>The Helm chart version is unified with the app version — <code>Chart.yaml</code> <code>version</code> and <code>appVersion</code> are dynamically set to the release tag by <code>helm_release.sh</code> at release time.</p><p>Users install the chart via:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plik</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://root-gg.github.io/plik</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plik</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plik/plik</span></span></code></pre></div><p>The chart source lives in <code>charts/plik/</code>. See the chart&#39;s <code>values.yaml</code> for all configuration options.</p><h3 id="pre-release-checklist" tabindex="-1">Pre-release checklist <a class="header-anchor" href="#pre-release-checklist" aria-label="Permalink to &quot;Pre-release checklist&quot;">​</a></h3><p>Before creating a GitHub release:</p><ol><li>Update the version badge and install snippets in <code>README.md</code> to reference the new tag</li><li>Move <code>charts/plik/CHANGELOG.md</code> entries from <code>[Unreleased]</code> to the new version heading (e.g. <code>[1.4-RC4] - 2026-02-21</code>)</li><li>Ensure all <code>ARCHITECTURE.md</code> files reflect any structural changes</li></ol>`,7))])}const P=o(h,[["render",u]]);export{v as __pageData,P as default};
